const KEY='story-studio-library-v2';
const DEMO={id:'coastal-star',title:'별을 기다리는 사람',status:'prototype',revision:1,story_revision:1,source_text:'열차가 끊긴 바닷가 역에서 서윤은 돌아오지 않는 약속을 기다린다. 작은 별이 손바닥에 내려앉는다. 뒤를 돌아본 서윤은 멀리 다가오는 열차의 불빛을 발견한다.',premise:'열차가 끊긴 바닷가 역에서, 잊힌 약속을 기다리는 서윤이 작은 별을 발견한다.',characters:'서윤 · 짧은 검은 머리, 짙은 코트. 쉽게 포기하지 않지만 자신의 기다림을 설명하지 못한다.',world:'마지막 열차가 사라진 해안역. 별은 잊힌 약속이 돌아올 때 땅에 내려온다.',episode:{id:'ep1',title:'돌아오는 약속',synopsis:'기다림에서 발견, 재회의 예감으로.'},plan:null,panels:[{id:1,title:'마지막 열차가 떠난 자리',scene_id:'scene1',story_revision:1,image:'panel-1.jpg',dialogue:'오늘도, 여기서 기다린다.',narration:'바다는 아무 대답도 하지 않았다.',intent:'고요한 기다림. 넓은 구도로 해안역과 서윤의 거리를 보여준다.',motion:'천천히 다가가는 카메라, 코트 자락에 부는 바람',duration:5},{id:2,title:'손안에 내려온 별',scene_id:'scene2',story_revision:1,image:'panel-2.jpg',dialogue:'아직 잊지 않았구나.',narration:'작은 빛이 손바닥 위에 내려앉았다.',intent:'기다림에서 발견으로. 손과 별의 빛에 시선을 모은다.',motion:'서윤이 손을 천천히 펴고, 별빛이 손바닥에 내려앉음',duration:4},{id:3,title:'익숙한 빛',scene_id:'scene3',story_revision:1,image:'panel-3.jpg',dialogue:'여기 있었구나.',narration:'멀리서, 오래전의 열차 소리가 들렸다.',intent:'기억과 재회의 예감. 시선이 바다에서 선로로 돌아간다.',motion:'서윤이 천천히 뒤를 돌아봄, 멀리 열차 불빛',duration:6}]};
const copy=x=>JSON.parse(JSON.stringify(x));const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeImage(s){return typeof s==='string'&&(/^(comic|panel-[123])\.jpg$/.test(s)||/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(s))?s:''}
function str(s,max=12000){if(typeof s!=='string'||s.length>max)throw new Error('텍스트 형식을 확인해주세요.');return s}
function integer(n){if(!Number.isSafeInteger(n)||n<1||n>1000000)throw new Error('버전 형식을 확인해주세요.');return n}
function normalize(raw){if(!raw||!Array.isArray(raw.panels)||raw.panels.length<1||raw.panels.length>100)throw new Error('작품에는 1~100개의 컷이 필요합니다.');const panels=raw.panels.map((p,i)=>({id:String(p.id??i+1),scene_id:String(p.scene_id??'scene'+(i+1)),story_revision:integer(p.story_revision??raw.story_revision??1),title:str(p.title,200),dialogue:str(p.dialogue??''),narration:str(p.narration??''),intent:str(p.intent??''),motion:str(p.motion??'장면의 움직임을 정해주세요.'),duration:typeof p.duration==='number'&&p.duration>0&&p.duration<=60?p.duration:4,image:safeImage(p.image??(raw.title===DEMO.title?'panel-'+((i%3)+1)+'.jpg':''))}));let plan=null;if(raw.plan){const q=raw.plan;if(!Array.isArray(q.shots)||q.shots.length>200)throw new Error('영상 계획 형식을 확인해주세요.');plan={id:String(q.id??'plan'),story_revision:integer(q.story_revision),comic_revision:integer(q.comic_revision),created_at:str(q.created_at??'',100),shots:q.shots.map((s,i)=>({id:String(s.id??i+1),source_panel:String(s.source_panel),image:safeImage(s.image),title:str(s.title??'',200),duration:typeof s.duration==='number'&&s.duration>0&&s.duration<=60?s.duration:4,framing:str(s.framing??'',200),camera_motion:str(s.camera_motion??'',1000),character_motion:str(s.character_motion??'',1000),environment_motion:str(s.environment_motion??'',1000),dialogue:str(s.dialogue??''),narration:str(s.narration??''),sound:str(s.sound??'',1000),motion_intent:str(s.motion_intent??'',1000)}))}}return{id:String(raw.id??crypto.randomUUID()),title:str(raw.title,200),status:'prototype',revision:integer(raw.revision??raw.comic_revision??1),story_revision:integer(raw.story_revision??1),source_text:str(raw.source_text??'',20000),premise:str(raw.premise??''),characters:str(raw.characters??''),world:str(raw.world??''),episode:{id:String(raw.episode?.id??'ep1'),title:str(raw.episode?.title??'첫 번째 이야기',200),synopsis:str(raw.episode?.synopsis??'')},panels,plan}}
let library=[copy(DEMO)],activeId=DEMO.id,saveError='',storageConflict=false;
try{const saved=localStorage.getItem(KEY);if(saved){const d=JSON.parse(saved);if(d.schema!==2||!Array.isArray(d.stories)||d.stories.length>50)throw new Error('저장 형식을 확인해주세요.');library=d.stories.map(normalize);if(!library.length)library=[copy(DEMO)];activeId=library.some(x=>x.id===d.activeId)?d.activeId:library[0].id}}catch(e){saveError='저장된 작품을 읽지 못했습니다. 기존 저장값은 덮어쓰지 않습니다.';storageConflict=true}
let state=library.find(x=>x.id===activeId);const ui={view:'start',selected:0,readerWidth:'wide',draft:{title:'',text:''},tab:'text'};const main=document.getElementById('main');
function toast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3800)}
function persist(){if(storageConflict){saveError='다른 탭 또는 기존 저장과 충돌했습니다. 파일로 내보낸 뒤 새로고침해주세요.';updateStatus();return false}try{localStorage.setItem(KEY,JSON.stringify({schema:2,activeId:state.id,stories:library}));saveError='';updateStatus();return true}catch(e){saveError='브라우저 저장 실패 · 작품을 파일로 내보내주세요.';updateStatus();return false}}
function updateStatus(){document.getElementById('saveStatus').textContent=saveError||'이 브라우저에 자동 저장됨';document.getElementById('saveStatus').classList.toggle('save-error',Boolean(saveError));document.querySelector('.canon-pill').textContent=`이야기 ${state.story_revision}판 · 만화 ${state.revision}판`;document.querySelector('.sidebar-story b').textContent=state.title;document.querySelector('.sidebar-story p').textContent=state.premise;document.querySelector('.breadcrumb').textContent='내 이야기 / '+state.title}
window.addEventListener('storage',e=>{if(e.key===KEY){storageConflict=true;saveError='다른 탭에서 작품이 변경됐습니다. 내보내기 후 새로고침해주세요.';updateStatus();toast(saveError)}});
function navigate(view){if(!['start','library','workspace','reader','production'].includes(view))return;ui.view=view;history.replaceState(null,'','#'+view);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.body.classList.toggle('reading',view==='reader');render();window.scrollTo(0,0)}
function photo(p){const image=safeImage(p?.image);return image?`<img src="${esc(image)}" alt="${esc(p.title)}" loading="lazy">`:`<div class="empty-img">이 컷의 그림을 추가해주세요</div>`}
const heading=(eye,title,desc,action='')=>`<div class="heading"><div><div class="eyebrow">${eye}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${action}</div>`;
function render(){({start:renderStart,library:renderLibrary,workspace:renderWorkspace,reader:renderReader,production:renderProduction}[ui.view])();bind();updateStatus()}
function renderStart(){main.innerHTML=`<section class="start-surface"><div class="eyebrow">STORY STUDIO</div><h1>무슨 이야기를 만들까요?</h1><p class="intro">한 문장의 아이디어도, 이미 써둔 글도.<br>이야기에서 시작해 만화와 움직이는 장면으로 이어가세요.</p><div class="start-options"><button data-start="idea" class="${ui.tab==='idea'?'selected':''}"><b>아이디어에서 시작</b><span>처음 떠오른 장면을 적어보세요</span></button><button data-start="text" class="${ui.tab==='text'?'selected':''}"><b>글 붙여넣기</b><span>원문을 보존하며 장면으로 나누기</span></button><button data-go="library"><b>기존 작품 열기</b><span>이 브라우저에 저장된 이야기</span></button></div><form id="newStory" class="story-input"><label for="newTitle">이야기 제목 <span>선택</span></label><input id="newTitle" maxlength="200" placeholder="나의 첫 번째 이야기" value="${esc(ui.draft.title)}"><label for="sourceText">${ui.tab==='idea'?'어떤 장면이 떠올랐나요?':'이야기의 글'}</label><textarea id="sourceText" maxlength="20000" required placeholder="비 오는 역에서 마지막 열차를 기다리는 사람이 있었다.\n그의 손에 작은 별이 내려앉았다.\n멀리서 잊고 있던 약속이 빛으로 돌아왔다.">${esc(ui.draft.text)}</textarea><div class="input-bottom"><p>문장·문단을 3~5개 컷의 초안으로 구성합니다.<br>실시간 AI 생성은 연결되지 않았습니다. 그림은 직접 추가할 수 있습니다.</p><button class="primary" type="submit">이야기 구성하기</button></div></form><div class="start-demo"><span>완성된 예시를 먼저 살펴보세요</span><button id="openDemo">별을 기다리는 사람 · 3컷 웹툰</button></div><div class="notice">작품은 이 기기의 이 브라우저에만 저장됩니다. 다른 기기로 옮기거나 보관하려면 .story 파일을 내보내세요.</div></section>`}
function renderLibrary(){main.innerHTML=heading('내 이야기','이야기는 계속됩니다.','원본과 등장인물, 세계관을 지키며 다음 장면으로.','<button class="primary" data-go="start">새 이야기</button>')+`<div class="library-grid">${library.map(s=>`<article class="story-tile">${photo(s.panels[0])}<div class="story-tile-content"><div class="eyebrow">${s.id===DEMO.id?'예시 작품':'나의 작품'}</div><h2>${esc(s.title)}</h2><p>${esc(s.premise.slice(0,180))}</p><div class="story-stats"><span><b>${s.story_revision}판</b>이야기</span><span><b>${s.panels.length}컷</b>만화</span><span><b>${s.plan?'있음':'없음'}</b>영상 계획</span></div><button class="primary" data-open="${esc(s.id)}">계속 만들기</button></div></article>`).join('')}</div><div class="notice">이 브라우저에 ${library.length}개 작품이 저장되어 있습니다. .story 파일을 가져오면 현재 작품을 덮어쓰지 않고 새 작품으로 추가합니다.</div>`}
function renderWorkspace(){const p=state.panels[ui.selected];main.innerHTML=heading('첫 번째 에피소드 / 만화 작업실',state.title,`${state.panels.length}개의 컷으로 이어가는 이야기.`,'<button class="primary" data-go="reader">웹툰으로 읽기</button>')+`<div class="toolbar"><div class="tabs"><button class="selected">만화 편집</button><button data-go="production">제작 보기</button></div><div class="toolbar-meta">이야기 ${state.story_revision}판 · 만화 ${state.revision}판</div></div><div class="workspace-grid"><section class="panel-list" aria-label="만화 컷">${state.panels.map((p,i)=>`<article class="panel-card ${i===ui.selected?'selected':''}"><button class="select-panel" data-panel="${i}" aria-label="${i+1}번 컷 선택: ${esc(p.title)}"></button><div class="panel-image">${photo(p)}<span class="image-tag">컷 ${String(i+1).padStart(2,'0')}</span>${p.dialogue?`<span class="image-caption">“${esc(p.dialogue)}”</span>`:''}</div><div class="panel-info"><div><strong><span class="panel-num">${String(i+1).padStart(2,'0')}</span>${esc(p.title)}</strong><p>${esc(p.narration.slice(0,110))}</p></div></div></article>`).join('')}<button class="add-panel" id="addPanel">＋ 컷 추가</button></section><aside class="editor"><div class="editor-top">컷의 이야기<span>컷 ${String(ui.selected+1).padStart(2,'0')}</span></div><label class="field" for="panelTitle">장면 이름</label><input id="panelTitle" maxlength="200" value="${esc(p.title)}"><label class="field" for="dialogue">대사</label><textarea id="dialogue">${esc(p.dialogue)}</textarea><label class="field" for="narration">내레이션</label><textarea id="narration">${esc(p.narration)}</textarea><label class="field" for="intent">장면의 의도</label><textarea id="intent">${esc(p.intent)}</textarea><button class="primary" id="savePanel">컷에 반영하기</button><label class="image-upload">이 컷의 그림 바꾸기<input id="panelImage" type="file" accept="image/png,image/jpeg,image/webp"></label><div class="order-buttons"><button id="moveEarlier" ${ui.selected===0?'disabled':''}>앞으로 이동</button><button id="moveLater" ${ui.selected===state.panels.length-1?'disabled':''}>뒤로 이동</button></div><button class="secondary full" id="selectedPlan">이 컷의 영상 계획</button><div class="continuity"><b>이야기의 연속성</b>이전 컷: ${esc(state.panels[ui.selected-1]?.title??'이야기의 시작')}<br>다음 컷: ${esc(state.panels[ui.selected+1]?.title??'에피소드의 끝')}<p>이미지 수정은 이야기 원본의 사건을 자동으로 바꾸지 않습니다.</p></div><p class="small-text">편집 내용은 이 브라우저에 자동 저장됩니다.</p></aside></div><div class="statusbar"><span>${state.id===DEMO.id?'같은 서윤과 해안역을 그린 서로 다른 3장의 예시 이미지':'원문을 보존한 컷 초안 · 그림을 직접 추가해 완성하세요'}</span><button id="openSource">이야기 원본 확인</button></div>`}
function renderReader(){main.innerHTML=`<div class="reader-top"><button class="secondary" data-go="workspace">편집으로 돌아가기</button><div><button id="readerSize" class="secondary">${ui.readerWidth==='wide'?'좁게 읽기':'넓게 읽기'}</button><button class="secondary" data-go="production">영상 제작</button></div></div><article class="reader ${ui.readerWidth==='narrow'?'narrow':''}"><div class="reader-title"><div class="eyebrow">첫 번째 에피소드</div><h1>${esc(state.title)}</h1><p>${esc(state.episode.title)}</p></div>${state.panels.map((p,i)=>`<section class="reader-panel"><span class="reader-number">${String(i+1).padStart(2,'0')}</span>${photo(p)}<div class="reader-copy">${p.narration?`<p>${esc(p.narration)}</p>`:''}${p.dialogue?`<blockquote>${esc(p.dialogue)}</blockquote>`:''}</div></section>`).join('')}<div class="reader-end">${esc(state.episode.title)} · 끝<br><button class="secondary" data-go="workspace">다음 장면 다듬기</button></div></article>`}
function stale(){return Boolean(state.plan&&(state.plan.comic_revision!==state.revision||state.plan.story_revision!==state.story_revision))}
function makePlan(panelId=null){const panels=panelId?state.panels.filter(p=>String(p.id)===String(panelId)):state.panels;state.plan={id:crypto.randomUUID(),story_revision:state.story_revision,comic_revision:state.revision,created_at:new Date().toISOString(),shots:panels.flatMap((p,i)=>[{id:`${p.id}-A`,source_panel:String(p.id),title:p.title,image:p.image,duration:p.duration,framing:'미디엄 클로즈',camera_motion:'천천히 다가가기',character_motion:p.motion,environment_motion:state.id===DEMO.id?'바람에 코트가 가볍게 움직임':'장면의 공간과 분위기를 유지',dialogue:p.dialogue,narration:p.narration,sound:state.id===DEMO.id?'파도 + 낮은 진동음':'환경음 · 세부 선택 필요',motion_intent:'느리고 미묘한 움직임'}, {id:`${p.id}-B`,source_panel:String(p.id),title:p.title+' · 감정의 세부',image:p.image,duration:2.5,framing:'클로즈업',camera_motion:'고정',character_motion:state.id===DEMO.id&&String(p.id)==='2'?'빛이 손바닥에 내려앉음':'장면의 핵심 대상과 감정에 머물기',environment_motion:'배경의 연속성 유지',dialogue:'',narration:'',sound:state.id===DEMO.id?'파도 잔향':'환경음 잔향',motion_intent:'미묘한 움직임'}])};persist();navigate('production');toast('현재 이야기와 만화를 기준으로 영상 계획을 만들었습니다.')}
function renderProduction(){const q=state.plan;main.innerHTML=heading('영상 제작','같은 이야기, 새로운 움직임.','컷의 의도와 앞뒤 맥락을 장면별 촬영 계획으로 이어갑니다.','<button class="secondary" data-go="workspace">만화 편집으로</button>')+`<div class="flow-strip"><span><b>이야기 원본</b>${state.story_revision}판</span><span><b>만화</b>${state.revision}판</span><span><b>영상 계획 기준</b>${q?`이야기 ${q.story_revision}판 · 만화 ${q.comic_revision}판`:'아직 없음'}</span></div>${stale()?'<div class="notice stale" role="status"><b>영상 계획이 이전 버전을 기준으로 하고 있습니다.</b><br>이야기 또는 만화의 편집 내용은 기존 영상 계획을 덮어쓰지 않습니다. 내용을 확인한 뒤 새 계획으로 갱신하세요.</div>':''}<div class="production-layout"><section>${q?q.shots.map((s,i)=>`<article class="shot-card">${photo({image:s.image,title:s.title})}<div><small>컷 ${esc(s.source_panel)} → 촬영 장면 ${esc(s.id)}</small><h3>${esc(s.title)} · ${s.duration.toFixed(1)}초</h3><p><b>${esc(s.framing)}</b> · 카메라 ${esc(s.camera_motion)}</p><p>인물 · ${esc(s.character_motion)}</p><p>공간 · ${esc(s.environment_motion)}</p><p>움직임 · ${esc(s.motion_intent)}</p><p>소리 · ${esc(s.sound)}</p>${s.dialogue?`<p>대사 · ${esc(s.dialogue)}</p>`:''}</div></article>`).join(''):'<div class="plan-empty"><h2>한 컷은 여러 장면이 될 수 있습니다.</h2><p>만화의 컷마다 전체 움직임과 감정의 세부를 나누어<br>길이·구도·인물 움직임·소리를 함께 계획합니다.</p><button class="primary" id="createPlan">전체 컷으로 영상 계획 만들기</button></div>'}</section><aside class="editor"><div class="editor-top">제작 보기<span>계획 단계</span></div><label class="field" for="planPanel">계획할 컷</label><select id="planPanel">${state.panels.map((p,i)=>`<option value="${esc(p.id)}" ${i===ui.selected?'selected':''}>컷 ${i+1} · ${esc(p.title)}</option>`).join('')}</select><button class="primary" id="planSelected">선택한 컷으로 계획 만들기</button><button class="secondary full" id="refreshPlan">전체 컷으로 ${q?'새 계획 만들기':'계획 만들기'}</button>${q?'<button class="secondary full" id="exportPlan">영상 계획 내보내기</button>':''}<div class="notice">영상 생성과 편집기 연결은 이번 시제품 범위에 포함되지 않습니다. 이 화면은 컷을 촬영 장면으로 구체화하는 제작 계획입니다.</div><p class="small-text">새 계획을 만드는 버튼을 눌렀을 때만 기존 계획을 교체합니다.</p></aside></div>`}
function openStory(){const dialog=document.getElementById('canonDialog');dialog.innerHTML=`<form method="dialog"><button class="close" aria-label="닫기">×</button></form><div class="eyebrow">이야기의 바탕</div><h2>이야기 원본</h2><p>원문은 그대로 남습니다. 만화의 표현을 바꾸어도 원본의 사건은 자동으로 바뀌지 않습니다.</p><form id="storyForm"><label class="field" for="storyName">작품 제목</label><input id="storyName" maxlength="200" value="${esc(state.title)}"><label class="field" for="storyPremise">이야기의 핵심</label><textarea id="storyPremise">${esc(state.premise)}</textarea><div class="canon-grid"><section><label class="field" for="characters">등장인물</label><textarea id="characters">${esc(state.characters)}</textarea></section><section><label class="field" for="world">세계관</label><textarea id="world">${esc(state.world)}</textarea></section></div><details><summary>처음 입력한 글</summary><p class="source-copy">${esc(state.source_text)}</p></details><div class="notice">원본을 수정해도 기존 만화와 영상 계획은 유지됩니다. 관련 표현을 직접 확인해 반영하세요.</div><button class="primary" type="submit">이야기 원본에 반영</button></form>`;dialog.showModal();document.getElementById('storyForm').onsubmit=e=>{e.preventDefault();const title=document.getElementById('storyName').value.trim();if(!title){toast('작품 제목을 입력해주세요.');return}const next={title,premise:document.getElementById('storyPremise').value,characters:document.getElementById('characters').value,world:document.getElementById('world').value};if(Object.keys(next).some(k=>next[k]!==state[k])){Object.assign(state,next);state.story_revision++;persist()}dialog.close();render();toast('이야기 원본을 반영했습니다. 만화와 영상 계획은 유지됩니다.')}}
function createFromText(title,text){text=text.trim();if(!text)throw new Error('아이디어나 글을 입력해주세요.');if(library.length>=50)throw new Error('작품은 최대 50개까지 저장할 수 있습니다.');const sentences=text.split(/\n+|(?<=[.!?。])\s*|(?<=다\.)/u).map(x=>x.trim()).filter(Boolean);let segments=sentences.length?sentences:[text];if(segments.length<3){const parts=text.split(/(?<=,|，|;|;)\s*|\s+/).filter(Boolean);if(parts.length>=3){segments=[];const size=Math.ceil(parts.length/3);for(let i=0;i<parts.length;i+=size)segments.push(parts.slice(i,i+size).join(' '))}while(segments.length<3)segments.push('이 장면의 다음 사건을 적어주세요.')}const count=Math.min(5,segments.length),groups=Array.from({length:count},()=>[]);segments.forEach((s,i)=>groups[Math.min(count-1,Math.floor(i*count/segments.length))].push(s));const next={id:crypto.randomUUID(),title:title.trim()||text.slice(0,24),status:'prototype',revision:1,story_revision:1,source_text:text,premise:text.slice(0,1000),characters:'원문에 등장하는 인물의 이름·외모·관계를 정해주세요.',world:'원문 속 장소와 세계의 규칙을 정해주세요.',episode:{id:crypto.randomUUID(),title:'첫 번째 이야기',synopsis:text.slice(0,1000)},plan:null,panels:groups.map((lines,i)=>({id:i+1,scene_id:'scene'+(i+1),story_revision:1,title:'장면 '+(i+1),image:'',dialogue:'',narration:lines.join(' '),intent:i===0?'이야기의 시작과 인물을 보여준다.':i===count-1?'사건의 결과와 다음 이야기의 여운을 남긴다.':'원문의 사건을 이어간다.',motion:'장면의 움직임을 정해주세요.',duration:4}))};library.push(next);state=next;ui.selected=0;ui.draft={title:'',text:''};persist();navigate('workspace');toast('원문을 보존하고 이야기와 컷 초안을 구성했습니다.')}
function editPanel(){const p=state.panels[ui.selected];const title=document.getElementById('panelTitle').value;if(!title.trim())return false;const values={title,dialogue:document.getElementById('dialogue').value,narration:document.getElementById('narration').value,intent:document.getElementById('intent').value};if(Object.keys(values).some(k=>values[k]!==p[k])){Object.assign(p,values);state.revision++;persist();const c=main.querySelectorAll('.panel-info')[ui.selected];c.querySelector('strong').textContent=String(ui.selected+1).padStart(2,'0')+' '+p.title;c.querySelector('p').textContent=p.narration.slice(0,110);const image=main.querySelectorAll('.panel-image')[ui.selected];let caption=image.querySelector('.image-caption');if(!caption&&p.dialogue){caption=document.createElement('span');caption.className='image-caption';image.appendChild(caption)}if(caption)caption.textContent=p.dialogue?'“'+p.dialogue+'”':'';main.querySelector('.toolbar-meta').textContent=`이야기 ${state.story_revision}판 · 만화 ${state.revision}판`}return true}
function exportJSON(data,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('파일을 내보냈습니다.')}
async function importStory(file){if(!file)return;if(file.size>12*1024*1024)throw new Error('작품 파일은 12MB 이하로 가져올 수 있습니다.');const raw=JSON.parse(await file.text());const next=normalize(raw.story??raw);if(library.length>=50)throw new Error('작품은 최대 50개까지 저장할 수 있습니다.');next.id=crypto.randomUUID();library.push(next);state=next;ui.selected=0;persist();navigate('workspace');toast('작품을 새 항목으로 가져왔습니다.')}
function bind(){main.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));main.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{ui.tab=b.dataset.start;render()});main.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{state=library.find(s=>s.id===b.dataset.open);ui.selected=0;persist();navigate('workspace')});const demo=document.getElementById('openDemo');if(demo)demo.onclick=()=>{state=library.find(s=>s.id===DEMO.id);if(!state){state=copy(DEMO);library.push(state)}ui.selected=0;persist();navigate('workspace')};const form=document.getElementById('newStory');if(form){form.onsubmit=e=>{e.preventDefault();try{createFromText(document.getElementById('newTitle').value,document.getElementById('sourceText').value)}catch(e){toast(e.message)}};for(const [id,key] of [['newTitle','title'],['sourceText','text']])document.getElementById(id).oninput=e=>ui.draft[key]=e.target.value}main.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>{editPanel();ui.selected=+b.dataset.panel;render()});for(const id of ['panelTitle','dialogue','narration','intent']){const el=document.getElementById(id);if(el)el.oninput=editPanel}const save=document.getElementById('savePanel');if(save)save.onclick=()=>{if(editPanel()){render();toast('컷이 반영되어 자동 저장됐습니다.')}else toast('장면 이름을 입력해주세요.')};const add=document.getElementById('addPanel');if(add)add.onclick=()=>{if(state.panels.length>=100){toast('최대 100컷까지 구성할 수 있습니다.');return}state.panels.push({id:crypto.randomUUID(),scene_id:crypto.randomUUID(),story_revision:state.story_revision,title:'새로운 장면',image:'',dialogue:'',narration:'',intent:'이 장면의 사건과 감정을 정해주세요.',motion:'장면의 움직임을 정해주세요.',duration:4});ui.selected=state.panels.length-1;state.revision++;persist();render()};for(const [id,delta] of [['moveEarlier',-1],['moveLater',1]]){const b=document.getElementById(id);if(b)b.onclick=()=>{const next=ui.selected+delta;if(next<0||next>=state.panels.length)return;[state.panels[ui.selected],state.panels[next]]=[state.panels[next],state.panels[ui.selected]];ui.selected=next;state.revision++;persist();render()}}const image=document.getElementById('panelImage');if(image)image.onchange=async e=>{const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>1.5*1024*1024){toast('PNG·JPG·WebP, 1.5MB 이하 그림을 선택해주세요.');return}const panel=state.panels[ui.selected],owner=state;const reader=new FileReader();reader.onload=()=>{if(!safeImage(reader.result)){toast('그림 형식을 확인해주세요.');return}panel.image=reader.result;owner.revision++;persist();render();toast('그림을 바꿨습니다. 이야기 원본은 유지됩니다.')};reader.onerror=()=>toast('그림을 읽지 못했습니다.');reader.readAsDataURL(f)};for(const id of ['openSource']){const b=document.getElementById(id);if(b)b.onclick=openStory}const selected=document.getElementById('selectedPlan');if(selected)selected.onclick=()=>makePlan(state.panels[ui.selected].id);const plan=document.getElementById('planSelected');if(plan)plan.onclick=()=>makePlan(document.getElementById('planPanel').value);for(const id of ['createPlan','refreshPlan']){const b=document.getElementById(id);if(b)b.onclick=()=>makePlan()}const exportPlan=document.getElementById('exportPlan');if(exportPlan)exportPlan.onclick=()=>exportJSON({status:'plan_only',...state.plan},'video-plan.json');const size=document.getElementById('readerSize');if(size)size.onclick=()=>{ui.readerWidth=ui.readerWidth==='wide'?'narrow':'wide';render()}}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.getElementById('canonBtn').onclick=openStory;document.getElementById('exportBtn').onclick=()=>exportJSON({format:'story-studio',schema:2,story:state},state.title.replace(/[\\/:*?"<>|]/g,'_')+'.story');document.getElementById('importBtn').onclick=()=>document.getElementById('importFile').click();document.getElementById('importFile').onchange=async e=>{try{await importStory(e.target.files[0])}catch(e){toast('가져오기 실패: '+e.message)}finally{e.target.value=''}};document.querySelector('.brand').onclick=e=>{e.preventDefault();navigate('start')};navigate(location.hash.slice(1)||'start');
if(document.modelContext?.registerTool){const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});for(const tool of [{name:'read_comic',description:'Read the active story, comic revision and saved video plan without changing them.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({title:state.title,story_revision:state.story_revision,comic_revision:state.revision,panels:copy(state.panels),plan:copy(state.plan),plan_stale:stale()})},{name:'navigate_story_studio',description:'Open a studio view without modifying story content.',inputSchema:{type:'object',properties:{view:{type:'string',enum:['start','library','workspace','reader','production']}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!['start','library','workspace','reader','production'].includes(input.view))throw new Error('Invalid view');navigate(input.view);return{view:ui.view}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}}}
